int32_t __stdcall STATLIST_CalcStatWithPercentBonus(D2StatListExStrc * pStatList, eD2UnitStat eUnitStat, eD2UnitStat eStat, int32_t bIncludeBonus) {
    if (!pStatList) {
      return 0;
    }

    int32_t nPercentStatValue = STATLIST_GetStatValueByIdAndLayer(pStatList, eStat, 0);
    int32_t nValue = STATLIST_GetStatFromBaseArray(pStatList, eUnitStat, 0);
    int nBonusPart = 0;
    if (bIncludeBonus) {
      int32_t nFullStatValue;
      nBonusPart = STATLIST_GetStatValueByIdAndLayer(pStatList, eUnitStat, 0);
      nBonusPart -= nValue;
    }

    nPercentStatValue = DATATBLS::DataTbls::D2ApplyPercent(nValue, nPercentStatValue, 100);
    return nPercentStatValue + nBonusPart + nValue;
}

