int32_t __stdcall STATLIST_CopyStatsToBuffer(D2UnitStrc * pUnit, D2StatStrc * pStatBuf, int32_t nMaxCount) {
    if (!pUnit) {
      return 0;
    }

    D2StatListExStrc* pStatsEx = pUnit->pStatsEx;
    if (!pStatsEx) {
      return 0;
    }
    if (!(pStatsEx->sStatList.nFlags & 0x80000000U)) {
      return 0;
    }

    int nCopyCount = (int)pStatsEx->sFullStats.wStatCount;
    if (nCopyCount >= nMaxCount) {
      nCopyCount = nMaxCount;
    }

    D2StatKeyUnion* pStatCur = &pStatsEx->sFullStats.pStatInfo->uKey;
    D2StatKeyUnion* pStatEnd = pStatCur + nCopyCount * 2;
    for (; pStatCur < pStatEnd; pStatCur += 2) {
      pStatBuf->uKey = *pStatCur;
      pStatBuf->nStatValue = (int)d2_bits_of(pStatCur[1]);
      pStatBuf++;
    }

    return nCopyCount;
}

int32_t __stdcall CopyStatsToBuffer(D2StatListExStrc * pStatListEx, D2StatStrc * pOutput, int32_t nOutputSize) {
    if (!pStatListEx) {
      return 0;
    }

    int nStatsCount = (int)pStatListEx->sStatList.sBaseStats.wStatCount;
    if (nStatsCount >= nOutputSize) {
      nStatsCount = nOutputSize;
    }

    D2StatKeyUnion* pStatCur = &pStatListEx->sStatList.sBaseStats.pStatInfo->uKey;
    D2StatKeyUnion* pDVar1 = pStatCur + nStatsCount * 2;
    for (; pStatCur < pDVar1; pStatCur += 2) {
      pOutput->uKey = *pStatCur;
      pOutput->nStatValue = (int)d2_bits_of(pStatCur[1]);
      pOutput++;
    }

    return nStatsCount;
}

