void __stdcall STATLIST_MarkUnitStatsChanged(D2UnitStrc * pUnit) {
    eD2States eState;
    D2StatListExStrc* pActiveStatList;
    D2StatListExStrc* pStatsExRoot = pUnit->pStatsEx;
    if (!(pStatsExRoot && pStatsExRoot->sStatList.nFlags & 2)) {
      return;
    }

    D2StatListExStrc* pActiveNext = pStatsExRoot->pActiveHead;
    while (pActiveStatList = pActiveNext) {
      pActiveNext = pActiveStatList->sStatList.pPrevLink;
      if (pActiveStatList->sStatList.nFlags & 4) {
        eState = pActiveStatList->sStatList.eState;
        if (eState != STATE_none) {
          DATATBLS::ItemStats::SetState(pUnit, eState, 0);
        }
        if (!(pActiveStatList->sStatList.nFlags & 0x80000000U)) {
          FreeAnyStatList(pActiveStatList);
        }

        pActiveNext = pStatsExRoot->pActiveHead;
      }
    }

    pStatsExRoot->sStatList.nFlags &= -3;
}

// Iteratively removes all stats from pStatList whose value is non-zero (treating them as child-list references). For each iteration, binary-searches the base stat array for the first stat entry, removes it via STATLIST_RemoveStatFromArray, propagates the negated value through STATLIST_PropagateStatChange, and if the owner is a player notifies the stat tracking system. Loops until no stats remain. No-op on NULL input.
void __stdcall STATLIST_RemoveAllStats(D2StatListExStrc * pStatList) {
    int nMid;
    int nStatCount;
    int32_t nMidShiftedStat;
    int nStatValue;
    D2PoolManagerStrc* pMemory;
    D2StatStrc* pStatArray;
    if (!pStatList) {
      return;
    }

    short int wRemainingCount = pStatList->sStatList.sBaseStats.wStatCount;
    while (wRemainingCount > 0) {
      int nSearchIdx;
      nStatCount = (int)pStatList->sStatList.sBaseStats.wStatCount;
      pStatArray = pStatList->sStatList.sBaseStats.pStatInfo;
      nMidShiftedStat = pStatList->sStatList.sBaseStats.pStatInfo->uKey.nPackedStatId;
      nSearchIdx = 0;
      if (nStatCount > 0) {
        do {
          nMid = (nStatCount - nSearchIdx) / 2 + nSearchIdx;
          nStatValue = pStatArray[nMid].uKey.nPackedStatId;
          if (nMidShiftedStat > nStatValue) {
            nSearchIdx = nMid + 1;
            nMid = nStatCount;
          } else if (nStatValue <= nMidShiftedStat) {
            if (nMid >= 0) {
              pStatArray += nMid;
              if (pStatArray) {
                nSearchIdx = pStatArray->nStatValue;
                if (-nSearchIdx) {
                  pMemory = pStatList->sStatList.pMemory;
                  STATLIST_RemoveStatFromArray(pMemory, pStatArray, pMemory, &pStatList->sStatList.sBaseStats);
                  STATLIST_PropagateStatChange(pStatList, nMidShiftedStat, -nSearchIdx, nullptr);
                  if (pStatList->sStatList.nFlags & 0x80000000U && pStatList->sStatList.eOwnerType == UNIT_PLAYER) {
                    STATLIST_TrackChangedStat(nMidShiftedStat, pStatList);
                  }
                }
              }
            }

            break;
          }

          nStatCount = nMid;
        } while (nSearchIdx < nMid);
      }

      wRemainingCount = pStatList->sStatList.sBaseStats.wStatCount;
    }
}

void __stdcall STATLIST_RemoveAllStatsFromOverlay(D2UnitStrc * pUnit) {
    D2StatListExStrc* pStatsEx;
    if (!pUnit) {
      return;
    }

    pStatsEx = pUnit->pStatsEx;
    if (!pStatsEx) {
      return;
    }

    pStatsEx->sStatList.nFlags &= -257;
    pStatsEx = pUnit->pStatsEx;
    if (!(pStatsEx && pStatsEx->sStatList.nFlags & 0x80000000U)) {
      return;
    }

    pStatsEx = GetStatListByFlags(pStatsEx, 0x80);
    if (!pStatsEx) {
      return;
    }

    STATLIST_RemoveAllStats(pStatsEx);
}

// Walks the active child stat-list chain of pUnit and frees any timed (flag bit 2) stat lists whose timeout has expired. When nFrameNumber is 0, decrements each timeout counter by 1 and frees on reaching zero; otherwise frees all whose timeout field is <= nFrameNumber.
void __stdcall RemoveStatListAfterTimeout(D2UnitStrc * pUnit, int32_t nFrameNumber) {
    D2StatListExStrc* pNextStatList;
    uint32_t nFlags;
    if (!pUnit) {
      return;
    }

    D2StatListExStrc* pStatsExRoot = pUnit->pStatsEx;
    if (!(pStatsExRoot && pStatsExRoot->sStatList.nFlags & 0x80000000U)) {
      return;
    }

    D2StatListExStrc* pStatList = pStatsExRoot->pActiveHead;
    if (nFrameNumber) {
      for (; pStatList; pStatList = pNextStatList) {
        nFlags = pStatList->sStatList.nFlags;
        pNextStatList = pStatList->sStatList.pPrevLink;
        if (nFlags & 2 && pStatList->sStatList.nTimeout <= nFrameNumber) {
          if (!(nFlags & 0x80000000U)) {
            FreeAnyStatList(pStatList);
          }
          pNextStatList = pStatsExRoot->pActiveHead;
        }
      }
    } else {
      for (; pStatList; pStatList = pNextStatList) {
        nFlags = pStatList->sStatList.nFlags;
        pNextStatList = pStatList->sStatList.pPrevLink;
        if (nFlags & 2) {
          --pStatList->sStatList.nTimeout;
          if (pStatList->sStatList.nTimeout <= 0) {
            if (!(nFlags & 0x80000000U)) {
              FreeAnyStatList(pStatList);
            }
            pNextStatList = pStatsExRoot->pActiveHead;
          }
        }
      }
    }
}

void __stdcall STATLIST_MergeBaseStats(D2StatListExStrc * pStatListExDest, D2StatListExStrc * pStatListExSource) {
    if (!(pStatListExDest && pStatListExSource)) {
      return;
    }

    D2StatStrc* pStatInfo = pStatListExSource->sStatList.sBaseStats.pStatInfo;
    D2StatStrc* pStatEnd = pStatInfo + pStatListExSource->sStatList.sBaseStats.wStatCount;
    for (; pStatInfo < pStatEnd; pStatInfo++) {
      STATLIST_AddStatValue(pStatListExDest, (eD2UnitStat)pStatInfo->uKey.sKey.wStatIndex, pStatInfo->nStatValue, pStatInfo->uKey.sKey.wSubIndex);
    }
}

void __stdcall STATLIST_RecalcAfterRemove(D2UnitStrc * pUnit) {
    uint32_t _bIsStateActive;
    bool bIsStateActive;
    D2StatListExStrc* pPlayerStatsEx;
    if (!pUnit) {
      return;
    }

    D2StatListExStrc* pStatsExRoot = pUnit->pStatsEx;
    if (!(pStatsExRoot && pStatsExRoot->sStatList.nFlags & 0x80000000U)) {
      return;
    }

    D2StatListExStrc* pActiveNext = pStatsExRoot->pActiveHead;
    while (pPlayerStatsEx = pActiveNext) {
      pActiveNext = pPlayerStatsEx->sStatList.pPrevLink;
      if (pPlayerStatsEx->sStatList.eOwnerType != UNIT_ITEM && !(pPlayerStatsEx->sStatList.nFlags & 0x181U)) {
        _bIsStateActive = DATATBLS::ItemStats::STATES_DoesStateStayOnDeath(pUnit, pPlayerStatsEx->sStatList.eState);
        if (!_bIsStateActive) {
          if (!(pPlayerStatsEx->sStatList.nFlags & 0x80000000U)) {
            FreeAnyStatList(pPlayerStatsEx);
          }

          pActiveNext = pStatsExRoot->pActiveHead;
        }
      }
    }
}

// Clamps a unit's stamina, mana, and hitpoints to their respective maximum values by querying the minimum shifted stat value from ItemStatCost.txt (IDs 10, 8, 6) and calling STATLIST_AddStatValue with a negative delta when any resource exceeds its cap.
void __stdcall UpdateResourceStats(D2UnitStrc * pUnit) {
    int32_t nMinShiftedStatVal;
    if (!pUnit) {
      return;
    }

    D2StatListExStrc* pStatsEx = pUnit->pStatsEx;
    if (!pStatsEx) {
      return;
    }
    if (ITEMS::Items::sgptDataTable->nTxtItemStatCostSize <= 0xa || !(ITEMS::Items::sgptDataTable->pTxtItemStatCost + 10)) {
      nMinShiftedStatVal = 0;
    } else {
      /* ID 10 = stamina */ nMinShiftedStatVal = STATLIST_GetStatValueByKey(ITEMS::Items::sgptDataTable->pTxtItemStatCost + 10, pStatsEx, 0xa0000);
    }

    int32_t nTxtMaxResource = STATLIST_GetMaxStaminaFromUnit(pUnit);
    if (nMinShiftedStatVal > nTxtMaxResource && nTxtMaxResource - nMinShiftedStatVal) {
      STATLIST_AddStatValue(pStatsEx, UNITSTAT_stamina, nTxtMaxResource - nMinShiftedStatVal, 0);
    }

    pStatsEx = pUnit->pStatsEx;
    if (!pStatsEx) {
      nMinShiftedStatVal = 0;
    } else if (ITEMS::Items::sgptDataTable->nTxtItemStatCostSize <= 8 || !(ITEMS::Items::sgptDataTable->pTxtItemStatCost + 8)) {
      nMinShiftedStatVal = 0;
    } else {
      /* ID 8 = mana */ nMinShiftedStatVal = STATLIST_GetStatValueByKey(ITEMS::Items::sgptDataTable->pTxtItemStatCost + 8, pStatsEx, 0x80000);
    }

    nTxtMaxResource = STATLIST_GetMaxManaFromUnit(pUnit);
    if (nMinShiftedStatVal > nTxtMaxResource && nTxtMaxResource - nMinShiftedStatVal) {
      STATLIST_AddStatValue(pStatsEx, UNITSTAT_mana, nTxtMaxResource - nMinShiftedStatVal, 0);
    }

    pStatsEx = pUnit->pStatsEx;
    if (!pStatsEx) {
      nMinShiftedStatVal = 0;
    } else if (ITEMS::Items::sgptDataTable->nTxtItemStatCostSize <= 6 || !(ITEMS::Items::sgptDataTable->pTxtItemStatCost + 6)) {
      nMinShiftedStatVal = 0;
    } else {
      /* ID 6 = hitpoints */ nMinShiftedStatVal = STATLIST_GetStatValueByKey(ITEMS::Items::sgptDataTable->pTxtItemStatCost + 6, pStatsEx, 0x60000);
    }

    nTxtMaxResource = STATLIST_GetMaxLifeFromUnit(pUnit);
    if (!(nMinShiftedStatVal > nTxtMaxResource && nTxtMaxResource - nMinShiftedStatVal)) {
      return;
    }

    STATLIST_AddStatValue(pStatsEx, UNITSTAT_hitpoints, nTxtMaxResource - nMinShiftedStatVal, 0);
}

// After a gem/rune is socketed into pUnit2 (worn by pUnit), recalculates all op=6/7 dependent stats on pUnit. Iterates pUnit2's full stat list, finds stats with op-dependent cross-references (opStat1/2/3), recalculates their combined values, and writes them back via STATLIST_SetFullStatValue.
void __stdcall ItemUpdateStatsAfterSocketing(D2UnitStrc * pUnit, D2UnitStrc * pUnit2) {
    uint32_t nOpStatIndex;
    int32_t nCombinedStatVal;
    D2ItemStatCostTxt* pStatCostTxt;
    uint16_t wOpStatIndex;
    int nUnit2;
    short int* pnOpStat;
    D2UnitStrc* pOwnerUnit = pUnit;
    if (!(pUnit && pUnit2 && (pUnit->eUnitType == UNIT_PLAYER || pUnit->eUnitType == UNIT_MONSTER))) {
      return;
    }

    D2StatListExStrc* pItemStatsEx = pUnit2->pStatsEx;
    if (!(pItemStatsEx && pItemStatsEx->sStatList.nFlags & 0x80000000U)) {
      return;
    }

    D2StatStrc* pStatCur = pItemStatsEx->sFullStats.pStatInfo;
    D2StatStrc* pStatEnd = pStatCur + pItemStatsEx->sFullStats.wStatCount;
    D2DataTableTxtStrc* pDataTable = ITEMS::Items::sgptDataTable;
    for (; pStatCur < pStatEnd; pStatCur++) {
      uint32_t uVar1;
      uVar1 = (uint32_t)pStatCur->uKey.sKey.wStatIndex;
      if (false || (int)uVar1 >= pDataTable->nTxtItemStatCostSize) {
        pStatCostTxt = 0;
      } else {
        pStatCostTxt = pDataTable->pTxtItemStatCost + uVar1;
      }
      if ((uint8_t)(pStatCostTxt->op - 6) <= 1) {
        pnOpStat = &pStatCostTxt->opStat1;
        nUnit2 = 0x0;
        do {
          wOpStatIndex = (uint16_t)*pnOpStat;
          if (wOpStatIndex == 0xffff) {
            break;
          }

          nOpStatIndex = (uint32_t)(uint16_t)wOpStatIndex;
          if (false || (int)nOpStatIndex >= pDataTable->nTxtItemStatCostSize) {
            pStatCostTxt = 0;
          } else {
            pStatCostTxt = pDataTable->pTxtItemStatCost + nOpStatIndex;
          }

          nCombinedStatVal = STATLIST_CalcCombinedStatValue(pOwnerUnit->pStatsEx, nOpStatIndex << 0x10);
          STATLIST_SetFullStatValue(nOpStatIndex << 0x10, nCombinedStatVal, pStatCostTxt, pOwnerUnit, pOwnerUnit->pStatsEx);
          pnOpStat++;
          nUnit2++;
          pDataTable = ITEMS::Items::sgptDataTable;
        } while (nUnit2 < 3);
      }
    }
}

