void __stdcall STATLIST_SetItemStatActive(D2UnitStrc * pUnit, D2UnitStrc * pItem, int32_t bActive) {
    if (!(pUnit && pItem)) {
      return;
    }

    D2StatListExStrc* pStatsEx = pItem->pStatsEx;
    if (!pStatsEx) {
      return;
    }
    if (pItem->eUnitType == UNIT_ITEM) {
      eD2BodyLoc eItemBodyLoc;
      eItemBodyLoc = ITEMS::Items::GetBodyLocation(pItem);
      if (eItemBodyLoc == BODYLOC_SWAPPED_R_ARM || eItemBodyLoc == BODYLOC_SWAPPED_L_ARM) {
        STATLIST_DetachAndRecalc(pStatsEx);
        return;
      }
    }
    if (pStatsEx->sStatList.pUnitAttached == pUnit) {
      if (bActive) {
        if (pStatsEx->sStatList.nFlags & 0x40000000U) {
          STATLIST_ActivateItemStats(pUnit, pItem);
          return;
        }
      } else {
        if (!(pStatsEx->sStatList.nFlags & 0x40000000U)) {
          STATLIST_DeactivateItemStats(pUnit, pItem);
          return;
        }
      }
    } else {
      STATLIST_AttachStatListToUnit(pUnit, pStatsEx, bActive);
      pStatsEx->sStatList.pUnitAttached = pUnit;
    }
}

BOOL __stdcall STATLIST_ToggleStateDisabled(D2UnitStrc * pUnit, eD2States eState, int32_t bDisabled) {
    if (eState == STATE_none) {
      return 0;
    }

    D2StatListExStrc* pStateStatList = pUnit->pStatsEx;
    if (pStateStatList && pStateStatList->sStatList.nFlags & 0x80000000U) {
      pStateStatList = GetStatListByState(pStateStatList, eState);
      if (!pStateStatList) {
        return 0;
      }
      if (bDisabled) {
        if (!(pStateStatList->sStatList.nFlags & 0x2000U)) {
          STATLIST_DetachAndRecalc(pStateStatList);
          pStateStatList->sStatList.nFlags |= 0x2000;
          STATLIST_AttachStatListToUnit(pUnit, pStateStatList, 1);
          return 1;
        }
      } else {
        if (pStateStatList->sStatList.nFlags & 0x2000U) {
          STATLIST_DetachAndRecalc(pStateStatList);
          pStateStatList->sStatList.nFlags &= -8193;
          STATLIST_AttachStatListToUnit(pUnit, pStateStatList, 1);
          return 1;
        }
      }
    }

    return 0;
}

